style.css:
@-moz-document domain("roblox.com") {
body {
        background-color: #e3e3e3 !important;
        font-family: Arial, sans-serif !important;
        color: black !important;
    }

    /* Pasek nawigacyjny */
    .navbar, .navbar-static-top, #navigation {
        background-color: #232527 !important;
        border-bottom: 2px solid #3d3d3d !important;
    }

    .navbar a, .menu-item {
        color: #e6e6e6 !important;
        font-weight: normal !important;
    }

    .navbar a:hover {
        color: white !important;
        background-color: #333 !important;
    }

    /* Stare logo Roblox (2015/2016) */
    .navbar-brand > img {
        content: url("https://upload.wikimedia.org/wikipedia/en/thumb/5/51/Roblox_Logo_2015.svg/2560px-Roblox_Logo_2015.svg.png") !important;
        height: 45px !important;
    }

    /* Karty gier w stylu 2016 */
    .game-card-container, .game-card-thumb, .game-card-info {
        background-color: #f2f2f2 !important;
        border-radius: 0 !important;
        box-shadow: none !important;
    }

    /* Przyciski */
    .btn-primary {
        background-color: #0078D7 !important;
        border-color: #0063B1 !important;
        color: white !important;
    }

    .btn-primary:hover {
        background-color: #005a9e !important;
    }

    /* Ukrycie nowych elementów */
    .modern-ui, .avatar-editor-container, .game-carousel, .ads-container {
        display: none !important;
    }

    /* Klasyczna stopka */
    footer, .footer-container {
        background-color: #262626 !important;
        color: #cccccc !important;
        font-size: 12px !important;
    }
}
